using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var modelId = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL")
            ?? "gpt-4o";

        IChatClient evaluationModel =
            new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint), new Azure.AzureKeyCredential(
                Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key"))
            .GetChatClient(modelId)
            .AsIChatClient();

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(evaluationModel));
    }

    [TestMethod]
    public async Task Greeting_Response_IsRelevantAndCoherent()
    {
        await using var scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(Greeting_Response_IsRelevantAndCoherent));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        // Simulate a response from the chat agent
        var response = new ChatMessage(ChatRole.Assistant,
            "Hello! I'm here to help you with any questions or tasks you might have. How can I assist you?");

        messages.Add(response);

        await scenarioRun.EvaluateAsync(messages);

        scenarioRun.AssertNoFailures();
    }

    [TestMethod]
    public async Task Factual_Question_IsGroundedAndComplete()
    {
        await using var scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(Factual_Question_IsGroundedAndComplete));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = new ChatMessage(ChatRole.Assistant,
            "The capital of France is Paris.");

        messages.Add(response);

        await scenarioRun.EvaluateAsync(messages);

        scenarioRun.AssertNoFailures();
    }
}

